import{_ as r,l as i,o,c as s,v as a,p as l,x as t,d as c,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"符号插入与 LD_PRELOAD","description":"","frontmatter":{"title":"符号插入与 LD_PRELOAD","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/symbol-interposition.md","filePath":"cs/symbol-interposition.md","lastUpdated":1789023840000}'),_={name:"cs/symbol-interposition.md"};function h(E,e,D,m,A,L){const d=i("Mermaid");return o(),s("div",null,[e[1]||(e[1]=a('<h1 id="符号插入与-ld-preload" tabindex="-1">符号插入与 LD_PRELOAD <a class="header-anchor" href="#符号插入与-ld-preload" aria-label="Permalink to &quot;符号插入与 LD_PRELOAD&quot;">​</a></h1><div class="epigraph"><p>动态加载器按搜索序绑定符号：先出现的定义可插入（interpose）后来的。`LD_PRELOAD` 把用户库放到序首，用于包装 `malloc`，也能破坏意图。</p><footer>—— 据 ELF 符号绑定与 `LD_PRELOAD` 手册；Drepper, How to Write Shared Libraries；Levine 整理</footer></div><p>上一课<a href="/cs/static-vs-dynamic-link">静态对动态</a> 选择了动态世界。缺口是<strong>绑定次序</strong>：插入、<code>RTLD_NEXT</code>、<code>visibility</code> 如何限制。本课钉加载器语义，不写利用教程；只讲编译器/链接为何发 <code>protected</code>/<code>hidden</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>默认：全局符号可被预加载库覆盖。<code>malloc</code> 包装器靠此。代价：意外插入、ABI 劫持。链接器：<code>-Bsymbolic</code>、protected 可见性让引用绑到本 <code>.so</code> 内。缺口是<strong>绑定范围</strong>，不是 GOT 结构重画。</p><p><code>dlsym(RTLD_NEXT, &quot;malloc&quot;)</code> 找插入链上的下一个。</p><h3 id="插入不是静态弱符号" tabindex="-1">插入不是静态弱符号 <a class="header-anchor" href="#插入不是静态弱符号" aria-label="Permalink to &quot;插入不是静态弱符号&quot;">​</a></h3><p>弱符号是静态解析规则；插入是动态绑定。二者都「可被覆盖」，阶段不同。</p><p><span class="marginnote">Drepper 的 How to Write Shared Libraries。ld.so 手册。本课防御性：如何避免被插，以及合法包装。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要包装：写 <code>.so</code>，<code>LD_PRELOAD=./wrap.so</code>。要防：<code>hidden</code> 内部函数、<code>-fno-semantic-interposition</code>（GCC/Clang 允许假设不被插，便于优化）。LTO 在动态库里仍可能因插入放弃一些 IPO。</p>',11)),(o(),l(p,null,{default:t(()=>[n(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22LD_PRELOAD%22%5D%20--%3E%20BIND%5B%22%E5%8A%A0%E8%BD%BD%E5%99%A8%E7%BB%91%E5%AE%9A%22%5D%0A%20%20OBJ%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%20%2F%20%E5%85%B6%E5%AE%83%20.so%22%5D%20--%3E%20BIND%0A%20%20BIND%20--%3E%20SYM%5B%22%E8%8E%B7%E8%83%9C%E7%9A%84%E5%AE%9A%E4%B9%89%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>与 PGO/LTO：若假设无插入，可内联跨导出函数——旗必须与部署一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>循环：包装器调用真 <code>malloc</code> 须 <code>RTLD_NEXT</code>，否则递归爆栈。不要在 <code>.so</code> 构造函数里调用尚可被插的符号而不小心。</p><p>安全：预加载可替换加密函数——部署环境要控制环境变量。点名即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供恶意 hook 清单。后课默认：动态符号可被插入，除非可见性限制。下一课重定位类型：绑定最终怎么写进 GOT。</p><p>也不把 <code>LD_PRELOAD</code> 当容器编排课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态绑定有序，PRELOAD 在前可插入。</li><li>hidden/protected/symbolic 限制插入以恢复优化。</li><li>合法包装用 <code>RTLD_NEXT</code> 防递归。</li><li>出处：Drepper；ld.so；ELF；Levine。</li></ul>',9))])}const P=r(_,[["render",h]]);export{u as __pageData,P as default};
